package dev.mineagent.runtime.core.config;
import com.fasterxml.jackson.databind.ObjectMapper;import dev.mineagent.runtime.api.config.ConfigPatch;import java.util.*;
/** Explicit evidence; absence is UNKNOWN, never guessed from the model's name. */
public final class ModelCapabilityProfiles {
 public enum Support { UNKNOWN, YES, NO }
 public record Profile(UUID id,String baseUrl,String model,Support vision,Support tools,int contextTokens,String source,long revision,long observedAt){public Profile{Objects.requireNonNull(id);if(!AgentModelSettings.validModel(model)||!WebSettingsCatalog.safeUrl(baseUrl)||vision==null||tools==null||contextTokens<0||contextTokens>16_777_216||!Set.of("UNKNOWN","METADATA","MANUAL","PROBE").contains(source)||revision<0)throw new IllegalArgumentException("MODEL_CAPABILITY_PROFILE");}}
 private static final ObjectMapper JSON=new ObjectMapper();private static final String PREFIX="model.capability.";
 public static Profile read(Map<String,String> values,String base,String model){String url=AgentModelSettings.origin(base);for(var entry:values.entrySet())if(entry.getKey().startsWith(PREFIX)&&!entry.getValue().isBlank())try{var p=JSON.readValue(entry.getValue(),Profile.class);if(p.baseUrl().equals(url)&&p.model().equals(model))return p;}catch(Exception e){throw new IllegalStateException("MODEL_CAPABILITY_STATE_INVALID",e);}return new Profile(new UUID(0,0),url,model,Support.UNKNOWN,Support.UNKNOWN,0,"UNKNOWN",0,0);}
 public static Profile save(ServerConfigService config,String base,String model,long expected,Support vision,Support tools,int context,String source)throws Exception{synchronized(config){var snapshot=config.snapshot();var old=read(snapshot.values(),base,model);if(expected!=old.revision())throw new IllegalStateException("MODEL_CAPABILITY_STALE");var p=new Profile(old.revision()==0?UUID.randomUUID():old.id(),AgentModelSettings.origin(base),model,vision,tools,context,source,expected+1,System.currentTimeMillis());var result=config.apply(new ConfigPatch(snapshot.revision(),Map.of(PREFIX+p.id(),JSON.writeValueAsString(p))),true);if(!result.accepted())throw new IllegalStateException(result.errorCode());return p;}}
 public static void metadata(ServerConfigService config,String base,String model,Support vision,Support tools,int context)throws Exception{var old=read(config.snapshot().values(),base,model);if(Set.of("MANUAL","PROBE").contains(old.source())||old.vision()==vision&&old.tools()==tools&&old.contextTokens()==context)return;save(config,base,model,old.revision(),vision,tools,context,"METADATA");}
 public static Map<String,Object> wire(Profile p){return Map.of("vision",p.vision().name(),"tools",p.tools().name(),"contextTokens",p.contextTokens(),"source",p.source(),"revision",p.revision(),"model",p.model());}
 private ModelCapabilityProfiles(){}
}
